toolArgs.file_text:
.chat-layout {
    display: flex;
    height: calc(100vh - 3.5rem);
    overflow: hidden;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    border-right: 1px solid #e0e0e0;
    overflow-y: auto;
    background: #f8f9fa;
}

.chat-main {
    width: 55%;
    display: flex;
    flex-direction: column;
    transition: width 0.2s ease;
}

.chat-main-expanded {
    width: 80%;
}

.chat-thread-panel {
    width: 25%;
    min-width: 250px;
    border-left: 1px solid #e0e0e0;
    overflow-y: auto;
    background: #fafbfc;
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #6c757d;
    font-size: 1.1rem;
}

/* Channel List */
::deep .channel-list {
    padding: 1rem 0;
}

::deep .channel-list-header {
    padding: 0 1rem;
    margin-bottom: 0.5rem;
    font-size: 0.85rem;
    text-transform: uppercase;
    color: #6c757d;
