+    padding: 0.75rem 1.25rem;
+    border-top: 1px solid #e0e0e0;
+    background: #fff;
+}
+
+::deep .message-input textarea {
+    flex: 1;
+    resize: none;
+    border: 1px solid #ced4da;
+    border-radius: 6px;
+    padding: 0.5rem 0.75rem;
+    font-size: 0.9rem;
+    font-family: inherit;
+    outline: none;
+    transition: border-color 0.15s;
+}
+
+::deep .message-input textarea:focus {
+    border-color: #0d6efd;
+}
+
+::deep .send-btn {
+    align-self: flex-end;
+    background: #0d6efd;
+    color: #fff;
+    border: none;
+    border-radius: 6px;
+    padding: 0.5rem 1.1rem;
+    font-size: 0.88rem;
+    font-weight: 600;
+    cursor: pointer;
+    transition: background 0.15s;
+}
+
+::deep .send-btn:hover:not(:disabled) {
+    background: #0b5ed7;
+}
+
+::deep .send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread Panel */
+::deep .thread-panel {
+    display: flex;
+    flex-direction: column;
+    height: 100%;
+    padding: 0;
+}
+
+::deep .thread-header {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #e0e0e0;
+}
+
+::deep .thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+}
+
+::deep .close-btn {
+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 0.2rem 0.5rem;
+    border-radius: 4px;
+    color: #6c757d;
+}
+
+::deep .close-btn:hover {
+    background: #e9ecef;
+    color: #000;
+}
+
+::deep .thread-root-message {
+    padding: 0.75rem 1rem;
+    background: #e8f0fe;
+    border-bottom: 1px solid #e0e0e0;
+}
+
+::deep .thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 0.75rem 1rem;
+}
+
+::deep .thread-reply {
+    padding: 0.4rem 0;
+    border-bottom: 1px solid #f0f0f0;
+}
+
+::deep .thread-reply:last-child {
+    border-bottom: none;
+}
+

